    \begin{equation*}
	R_{s}(\tau)=\begin{cases}
	1 - h(\tau),\quad &\text{ for }0\le\tau\le (3-\sqrt{5})/4, \\
	(1-3\tau)\log\left(\frac{1+\sqrt{5}}{2}\right),\quad &\text{ for }(3-\sqrt{5})/4< \tau\le 1/3.
	\end{cases}
	\end{equation*}

 We choose $M$ and accordingly $t(0)=1/M$ such that it satisfies  $2^{(R_s(\tau)-\varepsilon)n}<M < 2^{(R_s(\tau)-\varepsilon/2)n}$ and  $-\log t(0) < (R_{s}(\tau)-\varepsilon/2)n$. By definition, we have that $e(0,n) \leq \tau n$ and $f(0,n) \geq (1-\tau) n$. For given $\alpha$ and $\beta$, we can compute

\begin{align*}
    g(0,n)=e(0,n) \log \alpha + f(0,n) \log \beta \geq (\tau \log \alpha + (1-\tau) \log \beta)n.
\end{align*}

Subject to the constraints $\alpha + \beta = 2$ and $\alpha \beta^2\le 1$, the function $\tau \log \alpha + (1-\tau) \log \beta$ reaches the maximum $R_s(\tau)$ when $ \alpha = 2\min(\tau,(3-\sqrt{5})/4)$ and $\beta = 2-\alpha$. To make use of Lemma~\ref{lem::moment with big true segment}, we take $\alpha$ slightly smaller than $2\min(\tau,(3-\sqrt{5})/4)$ to have

\begin{align*}
    g(0,n)=e(0,n) \log \alpha + f(0,n) \log \beta \geq \left(R_{s}(\tau) - \frac{\varepsilon}{10}\right)n > \frac{2}{5} \varepsilon n - 
    \log t(0).
\end{align*}

By applying Lemma~\ref{lem::moment with big true segment} with $\varepsilon_1=2\varepsilon/5$ and $\varepsilon_2=\varepsilon/5$, there exists a constant $\delta >0$ such that for all but finite $\alpha \in (0,1)$, there is a first moment $n_1$ satisfying $t(n_1) \geq \delta$ and furthermore

