        1-x(i-1) - \frac{\beta - \alpha}{2} x(i-1) - y(i-1) &\geq \frac{\beta - \alpha}{2}x(i-1),\\
        1-\beta x(i-1) - y(i-1) &\geq \frac{\beta - \alpha}{2} x(i-1).
    \end{align*}
    Therefore, we get
    \begin{equation}\label{eq:proof_prop_2_2}
        \frac{1-x(i-1)\beta}{y(i-1)\alpha} \geq \frac{\frac{\beta - \alpha}{2}x(i-1) + y(i-1)}{y(i-1)\alpha} = \frac{1}{\alpha} + \frac{x(i-1) \frac{\beta - \alpha}{2}}{y(i-1)\alpha}.
    \end{equation}
    By using the fact that $T(i-1)$ is balanced we get
