        \frac{1-x(i-1)-y(i-1)}{x(i-1)} &\geq \beta - \alpha,\\
        1-x(i-1)-y(i-1) &\geq (\beta - \alpha) x(i-1),\\
        1-x(i-1) - \frac{\beta - \alpha}{2} x(i-1) - y(i-1) &\geq \frac{\beta - \alpha}{2}x(i-1),\\
        1-\beta x(i-1) - y(i-1) &\geq \frac{\beta - \alpha}{2} x(i-1).
    \end{align*}

 We are first considering the case that both $T(i-1)$ and $T(i)$ are central. Whether there occurs an error or not it holds that
 \begin{equation*}
     u_2(i) - u_2(i-1) = -\log (4 x(i-1)\beta y(i-1) \alpha) + \log(4 x(i-1) y(i-1)) = -\log(\alpha \beta) > 0  ,
 \end{equation*}
 since $\alpha \beta < 1$.


 Now we consider the case that $T(i-1)$ is central and $T(i)$ is not central. Due to Proposition~\ref{prop::properties of functions}.\ref{it:: u1 is large and cross, then is central} there is no crossing and we know because of Proposition~\ref{prop::trivial stuff}.\ref{it::central to non-central without cross implies error} that an error occurred. It follows that
 \begin{equation*}
     u_2(i) - u_2(i-1) = \log\left(\frac{1-y(i)}{x(i)}\right) + \log(4x(i-1)y(i-1)) = \log\left(\frac{4(1-y(i)) y(i)}{\alpha \beta}\right).
 \end{equation*}
 Because $T(i)$ is not central we have that $\frac{1}{2} \leq y(i) \leq \frac{\beta}{2}$ where $y(i) = \frac{\beta}{2}$ minimizes the last logarithm, leading to
 \begin{equation*}
     \log\left(\frac{4(1-y(i)) y(i)}{\alpha \beta}\right) \geq \log 1 = 0  .
 \end{equation*}



 Next we are considering the case that $T(i-1)$ is not central and there occurs a crossing. Without loss of generality we consider that $l(i-1)<r(i-1)$. Due to Proposition~\ref{prop::properties of functions}.\ref{it:: u1 is large and cross, then is central} we know that $T(i)$ is central and therefore we only have to consider this case. Then, it holds that
 \begin{align*}
     u_2(i) - u_2(i-1) &= -\log(4l(i)r(i)) - \log \left (\frac{1-r(i-1)}{l(i-1)} \right ) = -\log \left ( \frac{4(1-r(i-1))l(i)r(i)}{l(i-1)} \right) \\
     &= -\log(4\beta(1-r(i-1)) r(i)) .
 \end{align*}
 Next we use that $r(i) = 1-\beta(t(i-1) + l(i-1)) = \frac{\alpha}{2} + \beta \left(r(i-1) - \frac{1}{2}\right)$ and obtain
 \begin{equation*}
     -\log(4\beta(1-r(i-1)) r(i)) = -\log\left(4\beta(1-r(i-1)) \left(\frac{\alpha}{2} + \beta \left(r(i-1) - \frac{1}{2}\right)\right) \right).
 \end{equation*}
 By looking at the quadratic form (in $r(i-1)$) we find its maximum for $r(i-1) = \frac{3 \beta - \alpha}{4\beta}$ and 
 \begin{equation*}
    -\log\left(4\beta(1-r(i-1)) \left(\frac{\alpha}{2} + \beta \left(r(i-1) - \frac{1}{2}\right)\right) \right) \geq -\log\left((\beta + \alpha)\left(\frac{\alpha}{2} + \frac{\beta - \alpha}{4}\right)\right) = -\log 1 = 0  .
 \end{equation*}






  It remains to check the case when $T(i-1)$ is not central and there is no crossing. The true segment $T(i)$ can be either central, or non-central. Since $\frac{1}{4x(i)y(i)} \geq \frac{1-y(i)}{x(i)}$, it holds that
 \begin{equation*}
     u_2(i) - u_2(i-1) \geq \log \left (\frac{1-y(i)}{x(i)} \right )  - \log \left (\frac{1-y(i-1)}{x(i-1)}\right ) = 0.
 \end{equation*}
 The last equality holds since there is no crossing and, thus, we have
 $$
     1-y(i)  = \begin{cases}
