    v_2(i) - v_2(i-1) =  -\log(2y(i))+\log(2y(i-1))= -\log(2x(i-1) \beta) + \log(2y(i-1)) \geq -\log \beta  .
\end{equation*}

For the remainder of the proof we are considering cases without a crossing.
We consider the case that $T(i-1)$ and $T(i)$ are central. We obtain that
\begin{equation*}
    v_2(i) - v_2(i-1) = \log\left(\frac{y(i-1)}{y(i)}\right) = \begin{cases}
    -\log \alpha \geq \log \beta, \quad \text{if the transmission was correct},\\
    -\log \beta \geq \log \alpha, \quad \text{if the transmission was incorrect}.
    \end{cases}
\end{equation*}

Next we consider the case that $T(i-1)$ is central and $T(i)$ is not central. This can only occur in the incorrect case (Proposition~\ref{prop::trivial stuff}.\ref{it::central to non-central without cross implies error}) and then
\begin{equation*}
    v_2(i) - v_2(i-1) = \log(2(1-y(i))) + \log(2y(i-1)) = \log(4(1-y(i))y(i)) - \log \beta,
\end{equation*}
but since $y(i-1)\leq \frac{1}{2}$ we know that $y(i) \leq \frac{\beta}{2}$ and we get
\begin{equation*}
  v_2(i) - v_2(i-1)=  \log(4(1-y(i)) y(i)) - \log \beta \geq \log(\alpha \beta) - \log \beta = \log \alpha.
\end{equation*}
In the considered case, it also holds that $v_2(i-1) < \log \beta$ since the following statements are equivalent
\begin{align*}
    v_2(i-1) &< \log \beta,\\
    -\log(2y(i-1)) &< \log \beta,\\
    \frac{1}{2} &< \beta y(i-1) = y(i),
\end{align*}
where the last inequality holds because $T(i)$ is not central.



Now we consider the case that $T(i-1)$ and $T(i)$ are both not central and there is no crossing. In this case it holds that
\begin{align*}
    v_2(i) - v_2(i-1) &= \log(2(1-y(i))) - \log(2(1-y(i-1))) = \log\left(\frac{t(i) + x(i)}{t(i-1) + x(i-1)}\right) \\
    &= \begin{cases}
        \log \beta, \quad \text{if the transmission was correct},\\
        \log \alpha, \quad \text{if the transmission was incorrect}. 
    \end{cases}
\end{align*}
We show that $v_2(i-1)<\log \beta$ if the transmission was incorrect. It holds that
\begin{equation*}
    \log(2(1-y(i-1))) \leq -\log(2y(i-1))  .
\end{equation*}
It follows that $v_2(i-1)<\log \beta$ because the following statements are equivalent
\begin{align*}
    -\log(2y(i-1)) &< \log\beta ,\\
    \frac{1}{2y(i-1)} &< \beta ,\\
    \frac{1}{2} &< \beta y(i-1) = y(i) ,
\end{align*}
where the last line is true because $T(i)$ is not central and  the transmission was incorrect.

Finally we consider the case that $T(i-1)$ is not central but $T(i)$ is central. In this case, the transmission is correct since otherwise it holds $y(i)\ge y(i-1)\ge \frac{1}{2}$. Furthermore, recall that
\begin{equation*}
    -\log(2y(i)) \geq \log(2(1-y(i))) .
\end{equation*}
Therefore, we obtain
\begin{align*}
    v_2(i) - v_2(i-1) = -\log(2y(i)) - \log(2(1-y(i-1))) \geq \log\left(\frac{1-y(i)}{1-y(i-1)}\right)= \log \beta,
\end{align*}
which concludes the proof.

\begin{equation*}
        v_2(i) - v_2(i-1) = \log\left(\frac{y(i-1)}{y(i)}\right) = \begin{cases}
        -\log \alpha \geq \log \beta, \quad \text{if the transmission was correct},\\
