        &= \begin{cases}
            \log \beta, \quad \text{if the transmission was correct},\\
            \log \alpha, \quad \text{if the transmission was incorrect}. 
        \end{cases}
    \end{align*}

From Proposition~\ref{prop::properties of functions}.\ref{it:: is central and balanced} and the inequality~\eqref{eq::key inequality} we deduce that
\begin{equation}\label{eq::u2 big implies v2 big}
    v_2(i_0)>\frac{u_2(i_0)}{2}-\frac{\log(\beta/\alpha)}{2}\ge -\frac{1}{2}\log(\alpha^4\beta^6)\geq-\frac{1}{2}\log\beta^{-2}=\log\beta.
\end{equation}
Since $v_2(i_0)=-\log (2y(i_0))>\log\beta$, we have $y(i_0)<1/(2\beta)$.    From $y(i_0)<1/(2\beta)$ we obtain that 
\begin{equation*}
    u_1(i_0)=\log\left(\frac{1-y(i_0)-x(i_0)}{x(i_0)}\right)\geq\log \left(\frac{1-2y(i_0)}{y(i_0)}\right)> u_1'.
\end{equation*}
From Proposition~\ref{prop::u1increasing} it follows that 
$u_1(i)\geq u_1'$ for all $i\geq i_0$. Proposition~\ref{prop::u2increasing} implies that $u_2(i)\geq c$ for all $i\geq i_0$. Using  arguments as in~\eqref{eq::u2 big implies v2 big}, we get $v_2(i)>\log\beta$ for all $i$ such that $T(i)$ is central and balanced. Note that since $c\geq u_2'$
, the inequality $u_2(i)\geq u_2'$ holds.

Say that there are crossings at the moments $j_1, \ldots, j_k$, $i_0\leq j_1<\ldots<j_k<i_1$. Partition $[i_0, i_1)$ into the union $[i_0, j_1)\cup [j_1, j_1+1)\cup[j_1+1, j_2]\cup \ldots \cup [j_k, i_1)$. By Proposition~\ref{prop::properties of functions}.\ref{it:: cross, then balanced} and~\ref{prop::properties of functions}.\ref{it:: u2 is large and cross, then is central} the true segment is central and balanced at all the endpoints of the segments. Thus, all conditions of Proposition~\ref{prop::u2 and g} are satisfied. Moreover, if we prove the inequality~\eqref{eq::g and u_2} for these segments, it would also be true for their union. Therefore, it is sufficient to consider only two cases: 
\begin{enumerate}
    \item $i_1=i_0+1$ and there is a crossing.
    \item there is no crossing between $i_0$ and $i_1$.
\end{enumerate}

The first case is trivial. There is a crossing between $i_0$ and $i_1=i_0+1$, hence the transmission is correct by Proposition~\ref{prop::trivial stuff}.\ref{it::cross implies correct transmission}. In this case $g(i_0, i_1)=\log\beta$. From the other hand $u_2(i_1)-u_2(i_0)=-\log(\alpha\beta)$ by Proposition~\ref{prop::u2increasing}, which is at least $\log\beta$ because of the inequality~\eqref{eq::key inequality}. 

Proceed to the second case, where there is no crossing between $i_0$ and $i_1$. The smallest part is always the same, therefore 
\begin{equation*}
    g(i_0, i_1)=e(i_0, i_1) \log\alpha + f(i_0, i_1)\log\beta=\log\left(\frac{x(i_1)}{x(i_0)}\right).
\end{equation*}
Denote $v_2(i_1)-v_2(i_0)$ and $u_2(i_1)-u_2(i_0)$ as $\Delta v_2$ and $\Delta u_2$ correspondingly.
Since $T(i_0)$ and $T(i_1)$ are central, we have
\begin{align*}
    \Delta u_2&=-\log (x(i_1)y(i_1))+\log (x(i_0)y(i_0))\\&=
-\log y(i_1)+\log y(i_0)-\log\left(\frac{x(i_1)}{x(i_0)}\right)\\&=
\Delta v_2-g(i_0, i_1),
\end{align*}
which is equivalent to 
\begin{equation*}
    g(i_0, i_1) = \Delta v_2-\Delta u_2.
\end{equation*}
Using Proposition~\ref{prop::properties of functions}.\ref{it::is central then} and~\ref{prop::properties of functions}.\ref{it:: is central and balanced} for moments $i_1$ and $i_0$ respectively, we obtain
\begin{equation*}
    g(i_0, i_1) = \Delta v_2-\Delta u_2\leq\frac{\Delta u_2+\log\left(\frac{\beta}{\alpha}\right)}{2}-\Delta u_2=\frac{-\Delta u_2+\log\left(\frac{\beta}{\alpha}\right)}{2}.
\end{equation*}
Recall that $y(i_0)<1/(2\beta)$, which implies that $y(i_0+1)<\frac{1}{2}$, i.e., $T(i_0+1)$ is central. Using Proposition~\ref{prop::u2increasing}, we deduce
\begin{equation*}
    \Delta u_2=u_2(i_1)-u_2(i_0+1) + u_2(i_0+1)-u_2(i_0)\geq -\log(\alpha\beta).
\end{equation*}
Using this inequality and the inequality~\eqref{eq::key inequality}, we have
\begin{align*}
    g(i_0, i_1)\leq \frac{-\Delta u_2+\log\left(\frac{\beta}{\alpha}\right)}{2}
    \leq \frac{\log(\alpha\beta)+\log\left(\frac{\beta}{\alpha}\right)}{2}=\log\beta
    \leq -\log(\alpha\beta)
    \leq \Delta u_2.
\end{align*}
